pub(super) fn input_schema() -> Value {
    let mut root = input_root();
    let definitions = [
        ("candidate".to_owned(), candidate()),
        ("target".to_owned(), target()),
        ("workspace".to_owned(), workspace()),
        ("listener".to_owned(), listener()),
        ("httpPlane".to_owned(), http_plane()),
        ("socketRelayPlane".to_owned(), socket_relay_plane()),
        ("socketResponderPlane".to_owned(), socket_responder_plane()),
        ("rule".to_owned(), rule()),
        ("ruleContent".to_owned(), rule_content()),
        ("httpRuleContent".to_owned(), http_rule_content()),
        ("socketRuleContent".to_owned(), socket_rule_content()),
        ("condition".to_owned(), condition()),
        ("documentPredicate".to_owned(), document_predicate()),
        ("unifiedAction".to_owned(), unified_action()),
        ("documentMutation".to_owned(), document_mutation()),
        ("httpAction".to_owned(), http_action()),
        ("terminalAction".to_owned(), terminal_action()),
        ("documentValue".to_owned(), document_value()),
        ("androidProfile".to_owned(), android_profile()),
        ("weakNetwork".to_owned(), weak_network()),
        ("materials".to_owned(), materials()),
        ("packageRef".to_owned(), package_ref()),
        ("jsonValue".to_owned(), json_value()),
    ]
    .into_iter()
    .collect::<Map<_, _>>();
    root.as_object_mut()
        .expect("candidate input root is an object")
        .insert("$defs".to_owned(), Value::Object(definitions));
    root
}
